DROP TABLE IF EXISTS T CASCADE;
CREATE TABLE T(rid SERIAL, c0 INTEGER NOT NULL,c1 INTEGER NOT NULL,c2 INTEGER,c3 INTEGER,c4 INTEGER,c5 INTEGER,c6 INTEGER,c7 INTEGER);
CREATE UNIQUE INDEX k0_0 ON T(c5,c6) WHERE c5 IS NOT NULL AND c6 IS NOT NULL;
CREATE UNIQUE INDEX k0_1 ON T(c6) WHERE c5 IS NULL AND c6 IS NOT NULL;
CREATE UNIQUE INDEX k0_2 ON T(c5) WHERE c6 IS NULL AND c5 IS NOT NULL;
CREATE UNIQUE INDEX k0_3 ON T((1)) WHERE c5 IS NULL AND c6 IS NULL;
CREATE OR REPLACE FUNCTION chk_k0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c5 IS NOT NULL AND NEW.c6 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c5 IS NOT NULL AND c6 IS NOT NULL AND c5=NEW.c5 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c6 IS NOT NULL AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c5 IS NOT NULL AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c6 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
