  IF (NEW.c6 IS NULL AND NEW.c5 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c5 IS NOT NULL AND c6 IS NOT NULL AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c6 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c5 IS NOT NULL AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c6 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  IF (NEW.c5 IS NULL AND NEW.c6 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c5 IS NOT NULL AND c6 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c6 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c5 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c6 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k0 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k0();
