  IF (NEW.c2 IS NULL AND NEW.c3 IS NOT NULL AND NEW.c6 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  IF (NEW.c3 IS NULL AND NEW.c2 IS NOT NULL AND NEW.c6 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  IF (NEW.c6 IS NULL AND NEW.c2 IS NOT NULL AND NEW.c3 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c3 IS NULL AND NEW.c6 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c6 IS NULL AND NEW.c3 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  IF (NEW.c3 IS NULL AND NEW.c6 IS NULL AND NEW.c2 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c3 IS NULL AND NEW.c6 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c6 IS NULL AND c3 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c6 IS NULL AND c2 IS NOT NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c6 IS NULL AND c0=NEW.c0) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k25 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k25 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k25();
